  <svg
    xmlns="http://www.w3.org/2000/svg"
    class="svg-inline--vue-svg-icons"
    viewBox="27 14 112 112"
    :role="props.title == null ? undefined : 'img'"
    :aria-hidden="props.title == null ? 'true' : undefined"
    :style="{ height: sizeStyle, ...iconSizeStyle(props.size) }"
  >
    <title v-if="props.title != null">{{ props.title }}</title>
    <defs>
      <!-- バインダー: 木材(明るい飴色→濃い茶) -->
      <linearGradient :id="boardGradId" x1="0" y1="0" x2="0.6" y2="1">
        <stop offset="0" stop-color="#d9a45c" />
        <stop offset="0.55" stop-color="#c08a41" />
        <stop offset="1" stop-color="#9c6c2c" />
      </linearGradient>
      <!-- 紙: 白 -->
      <linearGradient :id="paperGradId" x1="0" y1="0" x2="0" y2="1">
        <stop offset="0" stop-color="#ffffff" />
        <stop offset="0.85" stop-color="#eef0f4" />
        <stop offset="1" stop-color="#e2e5ec" />
      </linearGradient>
      <!-- クリップ金具: 明るいシルバー -->
      <linearGradient :id="clipGradId" x1="0" y1="0" x2="0" y2="1">
        <stop offset="0" stop-color="#e8edf6" />
        <stop offset="1" stop-color="#b9c4d9" />
      </linearGradient>
      <!-- めくれた角の裏面: 折り目(グラデーションの中央)の際をやや暗く、中ほどを最も明るく、先端へ向かって少し沈める -->
      <linearGradient :id="curlGradId" x1="1" y1="1" x2="0" y2="0">
        <stop offset="0.5" stop-color="#c3c8d2" />
        <stop offset="0.56" stop-color="#e6e9ef" />
        <stop offset="0.72" stop-color="#ffffff" />
        <stop offset="0.9" stop-color="#f1f3f6" />
        <stop offset="1" stop-color="#dde1e8" />
      </linearGradient>
    </defs>

    <!-- 接地影 -->
    <ellipse cx="82" cy="120" rx="48" ry="4" fill="#000000" opacity="0.13" />

    <!-- バインダー板(木材) -->
    <rect
