<script setup lang="ts">
import { computed, useId } from 'vue';
import { iconSizeStyle, toCssSize } from '@/internal/icon-size';

interface Props {
  /** 表示サイズ(高さ)。数値はpxとして扱う */
  size?: number | string;
  /** 読み上げ名。指定するとrole="img"と<title>を出力する。未指定なら装飾アイコンとして扱う */
  title?: string;
}
const props = withDefaults(defineProps<Props>(), {
  size: '1.2em'
});

const sizeStyle = computed((): string => toCssSize(props.size));

const uid = (useId() ?? 'cc').replace(/[^a-zA-Z0-9_-]/g, '') || 'cc';
const boardGradId = `clipcopy-board-${uid}`;
const paperGradId = `clipcopy-paper-${uid}`;
const clipGradId = `clipcopy-clip-${uid}`;
const curlGradId = `clipcopy-curl-${uid}`;
const clipBackTextId = `clipcopy-back-text-${uid}`;
const clipFrontTextId = `clipcopy-front-text-${uid}`;
</script>
